fn load_config(path: &Path) -> Result<Config, Error> {
    let text = fs::read_to_string(path)?;        // ?: no nested branch
    let Some(raw) = parse(&text) else {          // let-else: one flat guard
        return Err(Error::Malformed);
    };
    Ok(normalize(raw))                           // body stays at one level
}
